export function isTokenRefreshParams(value: unknown): value is T.TokenRefreshParams {
  return validateTokenRefreshParams(value).length === 0;
}

export function validateTokenRefreshResult(value: unknown): ValidationIssue[] {
  const errs: ValidationIssue[] = [];
  checkTokenRefreshResult(value, "", errs);
  return errs;
}
export function isTokenRefreshResult(value: unknown): value is T.TokenRefreshResult {
  return validateTokenRefreshResult(value).length === 0;
}

const PARAMS = new Map<string, (value: unknown) => ValidationIssue[]>([
  ["cmux.git.status", validateGitStatusParams],
  ["cmux.git.diff", validateGitDiffParams],
  ["cmux.router.hello", validateProviderHello],
  ["cmux.router.resolve", validateResolveParams],
  ["cmux.router.token.refresh", validateTokenRefreshParams],
  ["cmux.router.interfaces.list", validateInterfacesListParams],
  ["cmux.router.pages.list", validatePagesListParams],
  ["com.example.hello.greet.say", validateHelloParams],
]);
const RESULTS = new Map<string, (value: unknown) => ValidationIssue[]>([
  ["cmux.git.status", validateGitStatus],
  ["cmux.git.diff", validateGitDiff],
  ["cmux.router.hello", validateProviderWelcome],
  ["cmux.router.resolve", validateResolveResult],
  ["cmux.router.token.refresh", validateTokenRefreshResult],
  ["cmux.router.interfaces.list", validateInterfacesListResult],
  ["cmux.router.pages.list", validatePagesListResult],
  ["com.example.hello.greet.say", validateHelloResult],
]);
const EVENTS = new Map<string, (value: unknown) => ValidationIssue[]>([
  ["cmux.git.status.changed", validateGitStatus],
  ["com.example.hello.greet.ticks", validateHelloResult],
]);

/** Incoming-value validators for Session; null means the IR has no such op or event. */
export const schema: SessionSchema = {
  validateParams: (op, value) => PARAMS.get(op)?.(value) ?? null,
  validateResult: (op, value) => RESULTS.get(op)?.(value) ?? null,
  validateEvent: (event, value) => EVENTS.get(event)?.(value) ?? null,
};
